settings.custom_liquid:
{% assign video_url = "https://www.youtube.com/watch?v=rEISaNcqZdM" %}
{% assign video_id = video_url | split: 'v=' | last | split: '&' | first %}

{{ video_id }}


<div class="video-section">
  <iframe
    width="560"
    height="315"
    id="youtube-player" src="https://www.youtube.com/embed/rEISaNcqZdM?autoplay=1&mute=1&controls=0&&showinfo=0&loop=1"
    frameborder="0" 
    allow="autoplay; encrypted-media"
    allowfullscreen
  ></iframe>
</div>

<style>
.video-section {
  position: relative;
  overflow: hidden;
  width: 100%;
  height: 0;
  padding-bottom: 56.25%; /* Adjust the aspect ratio if needed */
}

.video-section iframe {
  width: 100%;
  height: 100%;
  position: absolute;
  top: 0;
  left: 0;
}

</style>

<script>
  document.addEventListener('DOMContentLoaded', function () {
    var player;
    function onYouTubeIframeAPIReady() {
      player = new YT.Player('youtube-player', {
        events: {
          'onReady': onPlayerReady
        }
      });
    }

    function onPlayerReady(event) {
      event.target.setPlaybackQuality('hd720');
    }

    var scriptTag = document.createElement('script');
    scriptTag.src = 'https://www.youtube.com/iframe_api';
    var firstScriptTag = document.getElementsByTagName('script')[0];
    firstScriptTag.parentNode.insertBefore(scriptTag, firstScriptTag);

    window.onYouTubeIframeAPIReady = onYouTubeIframeAPIReady;
  });
</script>
